// worker_section.gox spawns a dedicated Worker running a separate
// Go/WASM binary (worker/worker.go) and exchanges messages with it via
// browser.Worker, proving the round trip actually works end to end --
// not just that both binaries compile.
package main

import (
	"fmt"
	"syscall/js"

	"github.com/elaous/gojiberry/domrt/browser"
	"github.com/elaous/gojiberry/domrt/html"
)

func wireWorkerSection(document *html.Document) {
	w := browser.NewWorker("worker-bootstrap.js")

	w.OnMessage(func(data js.Value) {
		if data.Get("ready").Truthy() {
			// The worker's own goroutine scheduling isn't running until
			// this fires, so wait for it instead of posting on a timer
			// and hoping the worker is listening by then.
			w.PostMessage(map[string]any{"n": 100})
			return
		}
		n := data.Get("n").Int()
		count := data.Get("count").Int()
		document.GetElementByID("worker-result").SetTextContent(
			fmt.Sprintf("primes<=%d: %d", n, count))
	})
	w.OnError(func(err *html.JSError) {
		document.GetElementByID("worker-result").SetTextContent("error: " + err.Error())
	})

	document.GetElementByID("worker-send-50").AddEventListener("click", js.FuncOf(func(this js.Value, args []js.Value) any {
		w.PostMessage(map[string]any{"n": 50})
		return nil
	}))
}
